/*Table structure for table `fasilitas` */

DROP TABLE IF EXISTS `fasilitas`;

CREATE TABLE `fasilitas` (
  `idfasilitas` int(11) NOT NULL AUTO_INCREMENT,
  `nama` varchar(200) DEFAULT NULL,
  `keterangan` text DEFAULT NULL,
  `status` enum('Y','T') DEFAULT 'Y',
  `slug` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`idfasilitas`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `fasilitas` */

insert  into `fasilitas`(`idfasilitas`,`nama`,`keterangan`,`status`,`slug`,`created_at`) values (1,'Ruang Pertemuan','<p>Ruang pertemuan di rumah sakit adalah fasilitas yang disediakan untuk berbagai kegiatan yang melibatkan pertemuan antar staf medis, pasien, keluarga pasien, serta pihak-pihak lain yang berkepentingan. Ruang pertemuan ini dirancang untuk mendukung berbagai jenis acara seperti rapat medis, seminar, pelatihan, konsultasi keluarga, dan kegiatan administratif lainnya.</p><h4>Fasilitas yang Tersedia</h4><ol><li><p><strong>Ruang yang Luas dan Nyaman</strong>:</p><ul><li>Dirancang dengan baik untuk menampung sejumlah peserta dengan nyaman.</li><li>Dilengkapi dengan kursi dan meja yang dapat diatur sesuai kebutuhan pertemuan.</li></ul></li><li><p><strong>Peralatan Presentasi dan Multimedia</strong>:</p><ul><li><strong>Proyektor dan Layar</strong>: Untuk presentasi visual.</li><li><strong>Sistem Audio</strong>: Mikrofon dan speaker untuk memastikan komunikasi yang jelas.</li><li><strong>Komputer dan Koneksi Internet</strong>: Untuk presentasi digital dan akses informasi online.</li></ul></li><li><p><strong>Sistem Tata Udara dan Pencahayaan</strong>:</p><ul><li>Pendingin ruangan (AC) untuk kenyamanan.</li><li>Pencahayaan yang dapat disesuaikan untuk berbagai jenis acara.</li></ul></li><li><p><strong>Fasilitas Tambahan</strong>:</p><ul><li><strong>Papan Tulis dan Flipchart</strong>: Untuk diskusi dan brainstorming.</li><li><strong>Kopi dan Teh</strong>: Penyediaan minuman ringan untuk peserta.</li></ul></li></ol><h4>Kegunaan Ruang Pertemuan</h4><ol><li><p><strong>Rapat Staf Medis</strong>:</p><ul><li>Tempat untuk pertemuan rutin staf medis guna membahas kasus-kasus pasien, prosedur medis, dan pengembangan kebijakan.</li><li>Diskusi antar tim medis untuk koordinasi perawatan pasien.</li></ul></li><li><p><strong>Konsultasi dan Edukasi Pasien dan Keluarga</strong>:</p><ul><li>Ruang pertemuan dapat digunakan untuk menjelaskan diagnosis, rencana perawatan, dan prosedur medis kepada pasien dan keluarga mereka.</li><li>Sesi edukasi untuk membantu pasien dan keluarga memahami kondisi medis dan cara perawatan di rumah.</li></ul></li><li><p><strong>Seminar dan Pelatihan</strong>:</p><ul><li>Tempat untuk mengadakan seminar medis, pelatihan, dan workshop bagi staf medis dan non-medis.</li><li>Program pengembangan profesional untuk meningkatkan keterampilan dan pengetahuan staf rumah sakit.</li></ul></li><li><p><strong>Kegiatan Administratif</strong>:</p><ul><li>Ruang pertemuan dapat digunakan untuk pertemuan manajemen rumah sakit, pembahasan kebijakan, dan perencanaan strategis.</li><li>Tempat untuk wawancara kerja, negosiasi kontrak, dan kegiatan administratif lainnya.</li></ul></li></ol><h4>Keunggulan Ruang Pertemuan di Rumah Sakit Kami</h4><ul><li><strong>Lokasi yang Strategis</strong>: Terletak di dalam kompleks rumah sakit sehingga mudah diakses oleh staf medis dan pasien.</li><li><strong>Fasilitas Lengkap</strong>: Dilengkapi dengan teknologi dan peralatan modern untuk mendukung berbagai jenis pertemuan.</li><li><strong>Lingkungan yang Profesional dan Nyaman</strong>: Dirancang untuk menciptakan suasana yang kondusif untuk diskusi dan pembelajaran.</li><li><strong>Layanan Pendukung</strong>: Tim kami siap membantu dalam pengaturan dan operasional pertemuan, termasuk penyediaan peralatan dan kebutuhan logistik lainnya.</li></ul>','Y','ruang-pertemuan','2024-07-30 11:53:45'),(2,'Mushalla','<p>Mushalla atau tempat ibadah merupakan fasilitas penting yang disediakan di rumah sakit untuk memenuhi kebutuhan spiritual pasien, keluarga, dan staf medis. Ini adalah ruang yang dirancang untuk kegiatan ibadah seperti sholat, berdoa, dan refleksi spiritual.</p><h4>Fungsi dan Manfaat Mushalla di Rumah Sakit</h4><ol><li><p><strong>Kenyamanan Spiritual</strong>: Mushalla memberikan lingkungan yang tenang dan damai bagi pasien, keluarga, dan staf medis untuk melakukan ibadah sesuai dengan keyakinan agama mereka.</p></li><li><p><strong>Dukungan Kebutuhan Pasien</strong>: Pasien yang beragama Islam dapat menjalankan kewajiban ibadah seperti sholat lima waktu tanpa harus meninggalkan lingkungan rumah sakit.</p></li><li><p><strong>Mendukung Kesehatan Mental</strong>: Keberadaan mushalla dapat membantu mengurangi stres dan meningkatkan kesejahteraan mental pasien serta keluarga yang sedang menjalani perawatan jangka panjang di rumah sakit.</p></li><li><p><strong>Inklusivitas dan Keterbukaan</strong>: Memiliki mushalla menunjukkan komitmen rumah sakit untuk menghormati dan mendukung keberagaman kepercayaan agama pasien dan staf medis.</p></li></ol><h4>Fasilitas dan Desain Mushalla</h4><ul><li><p><strong>Ruang Sholat</strong>: Dilengkapi dengan perlengkapan sholat seperti sajadah, Al-Qur\'an, dan tempat wudhu yang bersih.</p></li><li><p><strong>Lokasi Strategis</strong>: Biasanya terletak di area yang mudah diakses baik untuk pasien maupun pengunjung, seperti dekat dengan ruang tunggu atau area publik.</p></li><li><p><strong>Desain Ramah dan Nyaman</strong>: Memiliki desain yang estetis dengan pencahayaan alami, dekorasi yang sederhana namun bersahaja, serta perabotan yang nyaman untuk beristirahat dan beribadah.</p></li></ul><h4>Keuntungan Mushalla di Rumah Sakit</h4><ul><li><p><strong>Pelayanan Holistik</strong>: Memberikan perawatan yang holistik dengan memperhatikan kebutuhan spiritual pasien selain perawatan medis dan fisik.</p></li><li><p><strong>Keterbukaan dan Toleransi</strong>: Menunjukkan komitmen rumah sakit untuk membangun lingkungan yang inklusif dan ramah bagi semua agama.</p></li><li><p><strong>Dukungan Kesejahteraan Pasien</strong>: Memberikan tempat yang aman dan mendukung bagi pasien untuk menjalankan ritual keagamaan mereka tanpa hambatan.</p></li></ul>','Y','mushalla','2024-07-30 11:53:50');

