/*Table structure for table `penunjang` */

DROP TABLE IF EXISTS `penunjang`;

CREATE TABLE `penunjang` (
  `idpenunjang` int(11) NOT NULL AUTO_INCREMENT,
  `nama` varchar(100) DEFAULT NULL,
  `keterangan` text DEFAULT NULL,
  `status` enum('Y','T') DEFAULT 'Y',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`idpenunjang`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `penunjang` */

insert  into `penunjang`(`idpenunjang`,`nama`,`keterangan`,`status`,`created_at`) values (1,'CSSD','-','Y','2024-07-30 11:41:39'),(2,'Farmasi','-','Y','2024-07-30 11:41:39'),(4,'Fisioterapi','-','Y','2024-07-30 11:41:39'),(5,'Gizi','-','Y','2024-07-30 11:41:39'),(6,'IPSRS','-','Y','2024-07-30 11:41:39'),(7,'Laboratorium','-','Y','2024-07-30 11:41:39'),(8,'Loundry','-','Y','2024-07-30 11:41:39'),(9,'Radiologi','-','Y','2024-07-30 11:41:39');

/*Table structure for table `pesan` */

DROP TABLE IF EXISTS `pesan`;

CREATE TABLE `pesan` (
  `idpesan` int(11) NOT NULL AUTO_INCREMENT,
  `tanggal` date DEFAULT NULL,
  `nama` varchar(200) DEFAULT NULL,
  `email` varchar(200) DEFAULT NULL,
  `judul` varchar(200) DEFAULT NULL,
  `pesan` text DEFAULT NULL,
  `status` enum('PB','UP') DEFAULT 'UP',
  `status_baca` enum('UR','RD') DEFAULT 'UR',
  `respon` text DEFAULT NULL,
  `admin` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`idpesan`)
) ENGINE=InnoDB AUTO_INCREMENT=514 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

